pub fn toString(self: TokenKind) []const u8 {
            return (switch (self) {
.at_keyword => "@-keyword",
.bad_string => "bad string token",
.bad_url => "bad URL token",
.cdc => "\"-->\"",
.cdo => "\"<!--\"",
.close_curly => "\"}\"",
.close_bracket => "\"]\"",
.close_paren => "\")\"",
.colon => "\":\"",
.comma => "\",\"",
.delim => |c| (switch (c) {
'&' => "\"&\"",
'*' => "\"*\"",
'|' => "\"|\"",
'^' => "\"^\"",
'$' => "\"$\"",
'.' => "\".\"",
'=' => "\"=\"",
'!' => "\"!\"",
'>' => "\">\"",
'-' => "\"-\"",
'+' => "\"+\"",
'/' => "\"/\"",
'~' => "\"~\"",
else => "delimiter",
}),
.dimension => "dimension",
.function => "function token",
.hash => "hash token",
.ident => "identifier",
.number => "number",
.open_curly => "\"{\"",
.open_square => "\"[\"",
.open_paren => "\"(\"",
.percentage => "percentage",
.semicolon => "\";\"",
.string => "string token",
.unquoted_url => "URL token",
.whitespace => "whitespace",
});
    }
};

pub fn DeinitGuard(comptime T: type) type {
    return struct {
        ptr: ?*T = null,
        __cp_dropped: bool = false,

pub fn __cp_deinit(self: *@This()) void {
            if (self.__cp_dropped) return;
            self.__cp_dropped = true;
                if (self.ptr) |p| {
                    _ = &p;
                    _ = p.deinit();
                    self.ptr = null;
                }
        }
    };
}

pub fn DeinitWithAllocGuard(comptime T: type) type {
    return struct {
        ptr: ?*T = null,
        allocator: Allocator,
        __cp_dropped: bool = false,

pub fn __cp_deinit(self: *@This()) void {
            if (self.__cp_dropped) return;
            self.__cp_dropped = true;
                if (self.ptr) |p| {
                    _ = &p;
                    _ = p.deinit(self.allocator);
                    self.ptr = null;
                }
        }
    };
}

