pub const VendorPrefix = packed struct(u8) {
    none: bool = false,
    webkit: bool = false,
    moz: bool = false,
    ms: bool = false,
    o: bool = false,
    __unused: u3 = 0,

pub fn toCss(self: VendorPrefix, dest: *Printer) PrintErr!void {
            const bits = self.asBits();
            const wk = (comptime VendorPrefix.asBits(.{ .webkit = true }));
            _ = &wk;
            const mz = (comptime VendorPrefix.asBits(.{ .moz = true }));
            _ = &mz;
            const ms_b = (comptime VendorPrefix.asBits(.{ .ms = true }));
            _ = &ms_b;
            const ob = (comptime VendorPrefix.asBits(.{ .o = true }));
            _ = &ob;
            return (switch (bits) {
wk => dest.writeStr("-webkit-"),
mz => dest.writeStr("-moz-"),
ms_b => dest.writeStr("-ms-"),
ob => dest.writeStr("-o-"),
else => {
{
            }
},
});
    }

pub inline fn eq(self: VendorPrefix, other: VendorPrefix) bool {
            return (self.asBits() == other.asBits());
    }

pub inline fn fromName(comptime name: []const u8) VendorPrefix {
            comptime {
            var vp: VendorPrefix = .{};
            _ = &vp;
            @field(vp, name) = true;
            return vp;

}
    }

pub inline fn orNone(self: VendorPrefix) VendorPrefix {
            return self._or(VendorPrefix{ .none = true });
    }

pub inline fn _or(self: VendorPrefix, other: VendorPrefix) VendorPrefix {
            if (self.isEmpty()) {
                return other;
            }
            return self;
    }

pub fn difference(left: @This(), right: @This()) @This() {
            return @bitCast((@as(u8, @bitCast(left)) - @as(u8, @bitCast(right))));
    }

pub fn isEmpty(self: VendorPrefix) bool {
            return (self == VendorPrefix{  });
    }

pub fn bitwiseAnd(a: @This(), b: @This()) @This() {
            return bun.bits.@"and"(@This(), a, b);
    }

pub fn asBits(self: VendorPrefix) u8 {
            return @bitCast(self);
    }

pub fn eql(self: VendorPrefix, other: @This()) bool {
            return (self == other);
    }
    pub const empty = VendorPrefix{  };
    pub const all = VendorPrefix{ .none = true, .moz = true, .ms = true, .o = true, .webkit = true };
    pub const NONE = VendorPrefix{ .none = true };
    pub const WEBKIT = VendorPrefix{ .webkit = true };
    pub const MOZ = VendorPrefix{ .moz = true };
    pub const MS = VendorPrefix{ .ms = true };
    pub const O = VendorPrefix{ .o = true };
    pub const FIELDS: []const []const u8 = (&.{ "webkit", "moz", "ms", "o", "none" });
};

