pub const Delimiters = packed struct(u8) {
    curly_bracket: bool = false,
    semicolon: bool = false,
    bang: bool = false,
    comma: bool = false,
    close_curly_bracket: bool = false,
    close_square_bracket: bool = false,
    close_parenthesis: bool = false,
    __unused: u1 = 0,

pub fn getDelimiter(comptime tag: @TypeOf(.enum_literal)) Delimiters {
            var empty = Delimiters{  };
            _ = &empty;
            @field(empty, @tagName(tag)) = true;
            return empty;
    }

pub fn fromByte(byte: ?u8) Delimiters {
            if (byte) |b| {
                _ = &b;
                return TABLE[@as(usize, @intCast(b))];
            }
            return .{};
    }
    const NONE: Delimiters = .{};
    const TABLE: [256]Delimiters = brk: {
            var table: [256]Delimiters = @splat(.{});
            _ = &table;
            table[cp_cast_int(usize, 59)] = getDelimiter(.semicolon);
            table[cp_cast_int(usize, 33)] = getDelimiter(.bang);
            table[cp_cast_int(usize, 44)] = getDelimiter(.comma);
            table[cp_cast_int(usize, 123)] = getDelimiter(.curly_bracket);
            table[cp_cast_int(usize, 125)] = getDelimiter(.close_curly_bracket);
            table[cp_cast_int(usize, 93)] = getDelimiter(.close_square_bracket);
            table[cp_cast_int(usize, 41)] = getDelimiter(.close_parenthesis);
            break :brk table;
    };
};

