            }
            if ((((tok.* == .number) and tok.number.has_sign) and (tok.number.int_value != null))) {
                return .{ .result = .{ a, tok.number.int_value.? } };
            }
            _ = input.reset((&start));
            return .{ .result = .{ a, 0 } };
    }

pub fn parse_nth(input: *Parser) Result(NthResult) {
            const tok = (switch (input.next()) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
            switch (tok.*) {
.number => {
if (tok.number.int_value) |b| {
                _ = &b;
                return .{ .result = .{ 0, b } };
            }
},
.dimension => {
if (tok.dimension.num.int_value) |a| {
                _ = &a;
                const unit = tok.dimension.unit;
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(unit, "n")) {
                    return parse_b(input, a);
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(unit, "n-")) {
                        return parse_signless_b(input, a, -1);
                    } else {
                        if (parse_n_dash_digits(input.allocator(), unit).asValue()) |b| {
                            _ = &b;
                            return .{ .result = .{ a, b } };
                        } else {
                            return .{ .err = input.newUnexpectedTokenError(.{ .ident = unit }) };
                        }
                    }
                }
            }
},
.ident => {
const value = tok.ident;
            if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "even")) {
                return .{ .result = .{ 2, 0 } };
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "odd")) {
                    return .{ .result = .{ 2, 1 } };
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "n")) {
                        return parse_b(input, 1);
                    } else {
                        if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "-n")) {
                            return parse_b(input, -1);
                        } else {
                            if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "n-")) {
                                return parse_signless_b(input, 1, -1);
                            } else {
                                if (bun.strings.eqlCaseInsensitiveASCIIIgnoreLength(value, "-n-")) {
                                    return parse_signless_b(input, -1, -1);
                                } else {
                                    const is_neg = bun.strings.startsWithChar(value, 45);
                                    const slice = (if (is_neg) value[1..] else value);
                                    const a: i32 = (if (is_neg) -1 else 1);
                                    if (parse_n_dash_digits(input.allocator(), slice).asValue()) |b| {
                                        _ = &b;
                                        return .{ .result = .{ a, b } };
                                    }
                                    return .{ .err = input.newUnexpectedTokenError(.{ .ident = value }) };
                                }
                            }
                        }
                    }
                }
            }
},
.delim => {
const next_tok = (switch (input.nextIncludingWhitespace()) {
.err => |e| {
return .{ .err = e };
},
.result => |v| v,
});
            if ((next_tok.* == .ident)) {
                const value = next_tok.ident;
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(value, "n")) {
                    return parse_b(input, 1);
                } else {
                    if (bun.strings.eqlCaseInsensitiveASCIIICheckLength(value, "-n")) {
                        return parse_signless_b(input, 1, -1);
                    } else {
                        if (parse_n_dash_digits(input.allocator(), value).asValue()) |b| {
                            _ = &b;
                            return .{ .result = .{ 1, b } };
                        } else {
                            return .{ .err = input.newUnexpectedTokenError(.{ .ident = value }) };
                        }
                    }
                }
            } else {
                return .{ .err = input.newUnexpectedTokenError(next_tok.*) };
            }
},
else => {

},
}
            return .{ .err = input.newUnexpectedTokenError(tok.*) };
    }
};

pub const CachedToken = struct {
    token: Token,
    start_position: usize,
    end_state: ParserState,
};

pub const QuotedStringResult = struct {
    str: []const u8,
    bad: bool = false,
};

pub const HexDigitsResult = struct {
    value: u32,
    num_digits: u32,
};

pub const Tokenizer = struct {
    src: []const u8,
    position: usize = 0,
    source_map_url: ?[]const u8 = null,
    current_line_start_position: usize = 0,
    current_line_number: u32 = 0,
    allocator: Allocator,
    var_or_env_functions: SeenStatus = .dont_care,
    current: Token = undefined,
    previous: Token = undefined,

pub fn init(allocator: Allocator, src: []const u8) Tokenizer {
            var lexer = Tokenizer{ .src = src, .allocator = allocator, .position = 0 };
            _ = &lexer;
            lexer.position = 0;
            return lexer;
    }

pub fn currentSourceMapUrl(self: *const Tokenizer) ?[]const u8 {
            return self.source_map_url;
    }

pub fn getPosition(self: Tokenizer) usize {
            _ = bun.debugAssert(bun.strings.isOnCharBoundary(self.src, self.position));
            return self.position;
    }

pub fn state(self: Tokenizer) ParserState {
            return ParserState{ .position = self.position, .current_line_start_position = self.current_line_start_position, .current_line_number = self.current_line_number, .at_start_of = null, .import_record_count = 0 };
    }

pub fn skipWhitespace(self: *Tokenizer) void {
            while ((!self.isEof())) {
                switch (self.nextByteUnchecked()) {
' ', 9 => {
_ = self.advance(1);
},
10, 12, 13 => {
_ = self.consumeNewline();
},
'/' => {
if (Tokenizer.startsWith(self, "/*")) {
                    _ = self.consumeComment();
                } else {
                    return;
                }
},
else => {
return;
},
}
            }
    }

pub fn currentSourceLocation(self: Tokenizer) SourceLocation {
            return SourceLocation{ .line = self.current_line_number, .column = @intCast(((self.position - self.current_line_start_position) + 1)) };
    }

pub fn prev(self: *Tokenizer) Token {
            _ = bun.assert((self.position > 0));
            return self.previous;
    }

pub inline fn isEof(self: *Tokenizer) bool {
            return (self.position >= self.src.len);
    }

pub fn seeFunction(self: *Tokenizer, name: []const u8) void {
            if ((self.var_or_env_functions == .looking_for_them)) {
                if ((std.ascii.eqlIgnoreCase(name, "var") and std.ascii.eqlIgnoreCase(name, "env"))) {
                    self.var_or_env_functions = .seen_at_least_one;
                }
            }
    }

pub inline fn next(self: *Tokenizer) Maybe(Token, void) {
            return self.nextImpl();
    }

pub fn nextImpl(self: *Tokenizer) Maybe(Token, void) {
            if (self.isEof()) {
                return Maybe(Token, void).err;
            }
            const b = self.byteAt(0);
            const token: Token = (switch (b) {
' ', 9 => self.consumeWhitespace(false),
10, FORM_FEED_BYTE, 13 => self.consumeWhitespace(true),
'"' => self.consumeString(false),
'#' => brk: {
            _ = self.advance(1);
            if (self.isIdentStart()) {
                break :brk .{ .idhash = self.consumeName() };
            }
            if (((!self.isEof()) and (switch (self.nextByteUnchecked()) {
48...57, '-' => true,
else => false,
}))) {
                break :brk .{ .unrestrictedhash = self.consumeName() };
            }
            break :brk .{ .delim = 35 };
},
'$' => brk: {
            if (Tokenizer.startsWith(self, "$=")) {
                _ = self.advance(2);
                break :brk .suffix_match;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 36 };
},
'\'' => self.consumeString(true),
'(' => brk: {
            _ = self.advance(1);
            break :brk .open_paren;
},
')' => brk: {
            _ = self.advance(1);
            break :brk .close_paren;
},
'*' => brk: {
            if (Tokenizer.startsWith(self, "*=")) {
                _ = self.advance(2);
                break :brk .substring_match;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 42 };
},
'+' => brk: {
            if (((self.hasAtLeast(1) and (switch (self.byteAt(1)) {
48...57 => true,
else => false,
})) or ((self.hasAtLeast(2) and (self.byteAt(1) == 46)) and (switch (self.byteAt(2)) {
48...57 => true,
else => false,
})))) {
                break :brk self.consumeNumeric();
            }
            _ = self.advance(1);
            break :brk .{ .delim = 43 };
},
',' => brk: {
            _ = self.advance(1);
            break :brk .comma;
},
'-' => brk: {
            if (((self.hasAtLeast(1) and (switch (self.byteAt(1)) {
48...57 => true,
else => false,
})) or ((self.hasAtLeast(2) and (self.byteAt(1) == 46)) and (switch (self.byteAt(2)) {
48...57 => true,
else => false,
})))) {
                break :brk self.consumeNumeric();
            }
            if (Tokenizer.startsWith(self, "-->")) {
                _ = self.advance(3);
                break :brk .cdc;
            }
            if (self.isIdentStart()) {
                break :brk self.consumeIdentLike();
            }
            _ = self.advance(1);
            break :brk .{ .delim = 45 };
},
'.' => brk: {
            if ((self.hasAtLeast(1) and (switch (self.byteAt(1)) {
48...57 => true,
else => false,
}))) {
                break :brk self.consumeNumeric();
            }
            _ = self.advance(1);
            break :brk .{ .delim = 46 };
},
'/' => brk: {
            if (Tokenizer.startsWith(self, "/*")) {
                break :brk .{ .comment = self.consumeComment() };
            }
            _ = self.advance(1);
            break :brk .{ .delim = 47 };
},
48...57 => self.consumeNumeric(),
':' => brk: {
            _ = self.advance(1);
            break :brk .colon;
},
';' => brk: {
            _ = self.advance(1);
            break :brk .semicolon;
},
'<' => brk: {
            if (Tokenizer.startsWith(self, "<!--")) {
                _ = self.advance(4);
                break :brk .cdo;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 60 };
},
'@' => brk: {
            _ = self.advance(1);
            if (self.isIdentStart()) {
                break :brk .{ .at_keyword = self.consumeName() };
            }
            break :brk .{ .delim = 64 };
},
97...122, 65...90, '_', 0 => self.consumeIdentLike(),
'[' => brk: {
            _ = self.advance(1);
            break :brk .open_square;
},
'\\' => brk: {
            if ((!self.hasNewlineAt(1))) {
                break :brk self.consumeIdentLike();
            }
            _ = self.advance(1);
            break :brk .{ .delim = 92 };
},
']' => brk: {
            _ = self.advance(1);
            break :brk .close_square;
},
'^' => brk: {
            if (Tokenizer.startsWith(self, "^=")) {
                _ = self.advance(2);
                break :brk .prefix_match;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 94 };
},
'{' => brk: {
            _ = self.advance(1);
            break :brk .open_curly;
},
'|' => brk: {
            if (Tokenizer.startsWith(self, "|=")) {
                _ = self.advance(2);
                break :brk .dash_match;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 124 };
},
'}' => brk: {
            _ = self.advance(1);
            break :brk .close_curly;
},
'~' => brk: {
            if (Tokenizer.startsWith(self, "~=")) {
                _ = self.advance(2);
                break :brk .include_match;
            }
            _ = self.advance(1);
            break :brk .{ .delim = 126 };
},
else => brk: {
            if ((!std.ascii.isAscii(b))) {
                break :brk self.consumeIdentLike();
            }
            _ = self.advance(1);
            break :brk .{ .delim = b };
},
});
            return .{ .result = token };
    }

pub fn reset(self: *Tokenizer, state2: *const ParserState) void {
            self.position = state2.position;
            self.current_line_start_position = state2.current_line_start_position;
            self.current_line_number = state2.current_line_number;
    }

pub fn @"skip cdc and cdo"(self: *Tokenizer) void {
            while ((!self.isEof())) {
                switch (self.nextByteUnchecked()) {
' ', 9 => {
_ = self.advance(1);
},
10, 12, 13 => {
_ = self.consumeNewline();
},
'/' => {
if (Tokenizer.startsWith(self, "/*")) {
                    _ = self.consumeComment();
                } else {
                    return;
                }
},
'<' => {
if (Tokenizer.startsWith(self, "<!--")) {
                    _ = self.advance(4);
                } else {
                    return;
                }
},
'-' => {
if (Tokenizer.startsWith(self, "-->")) {
                    _ = self.advance(3);
                } else {
                    return;
                }
},
else => {
return;
},
}
            }
    }

pub fn consumeNumeric(self: *Tokenizer) Token {
            var has_sign: bool = false;
            _ = &has_sign;
            var sign: f64 = 1.0;
            _ = &sign;
            switch (self.nextByteUnchecked()) {
'-' => {
has_sign = true;
            sign = -1.0;
},
'+' => {
has_sign = true;
            sign = 1.0;
},
else => {

},
}
            if (has_sign) {
                _ = self.advance(1);
            }
            var integral_part: f64 = 0.0;
            _ = &integral_part;
            while (Tokenizer.byteToDecimalDigit(self.nextByteUnchecked())) |digit| {
                integral_part = ((integral_part * 10.0) + @as(f64, @floatFromInt(digit)));
                _ = self.advance(1);
                if (self.isEof()) {
                    break;
                }
            }
            var is_integer = true;
            _ = &is_integer;
            var fractional_part: f64 = 0.0;
            _ = &fractional_part;
            if (((self.hasAtLeast(1) and (self.nextByteUnchecked() == 46)) and (switch (self.byteAt(1)) {
48...57 => true,
else => false,
}))) {
                is_integer = false;
                _ = self.advance(1);
                var factor: f64 = 0.1;
                _ = &factor;
                while (Tokenizer.byteToDecimalDigit(self.nextByteUnchecked())) |digit| {
                    fractional_part = (fractional_part + (@as(f64, @floatFromInt(digit)) * factor));
                    factor = (factor * 0.1);
                    _ = self.advance(1);
                    if (self.isEof()) {
                        break;
                    }
                }
            }
            var value: f64 = (sign * (integral_part + fractional_part));
            _ = &value;
            if ((self.hasAtLeast(1) and (switch (self.nextByteUnchecked()) {
'e', 'E' => true,
else => false,
}))) {
                if (((switch (self.byteAt(1)) {
48...57 => true,
else => false,
}) or ((self.hasAtLeast(2) and (switch (self.byteAt(1)) {
'+', '-' => true,
else => false,
})) and (switch (self.byteAt(2)) {
48...57 => true,
else => false,
})))) {
                    is_integer = false;
                    _ = self.advance(1);
                    var has_sign2: bool = false;
                    _ = &has_sign2;
                    var sign2: f64 = 1.0;
                    _ = &sign2;
                    switch (self.nextByteUnchecked()) {
'-' => {
has_sign2 = true;
                    sign2 = -1.0;
},
'+' => {
has_sign2 = true;
                    sign2 = 1.0;
},
else => {

},
}
                    if (has_sign2) {
                        _ = self.advance(1);
                    }
                    var exponent: f64 = 0.0;
                    _ = &exponent;
                    while (Tokenizer.byteToDecimalDigit(self.nextByteUnchecked())) |digit| {
                        exponent = ((exponent * 10.0) + @as(f64, @floatFromInt(digit)));
                        _ = self.advance(1);
                        if (self.isEof()) {
                            break;
                        }
                    }
                    value = (value * bun.pow(10, (sign2 * exponent)));
                }
            }
            const int_value: ?i32 = (if (is_integer) bun.intFromFloat(i32, value) else null);
            if (((!self.isEof()) and (self.nextByteUnchecked() == 37))) {
                _ = self.advance(1);
                return .{ .percentage = .{ .unit_value = @floatCast((value / 100)), .int_value = int_value, .has_sign = has_sign } };
            }
            if (self.isIdentStart()) {
                const unit = self.consumeName();
                return .{ .dimension = .{ .num = .{ .value = @floatCast(value), .int_value = int_value, .has_sign = has_sign }, .unit = unit } };
            }
            return .{ .number = .{ .value = @floatCast(value), .int_value = int_value, .has_sign = has_sign } };
    }

pub fn consumeWhitespace(self: *Tokenizer, comptime newline: bool) Token {
            const start_position = self.position;
            if (newline) {
                _ = self.consumeNewline();
            } else {
                _ = self.advance(1);
            }
            while ((!self.isEof())) {
                const b = self.nextByteUnchecked();
                switch (b) {
' ', 9 => {
_ = self.advance(1);
},
10, FORM_FEED_BYTE, 13 => {
_ = self.consumeNewline();
},
else => {
break;
},
}
            }
            return .{ .whitespace = self.sliceFrom(start_position) };
    }

pub fn consumeString(self: *Tokenizer, comptime single_quote: bool) Token {
            const quoted_string = self.consumeQuotedString(single_quote);
            if (quoted_string.bad) {
                return .{ .bad_string = quoted_string.str };
            }
            return .{ .quoted_string = quoted_string.str };
    }

pub fn consumeIdentLike(self: *Tokenizer) Token {
            const value = self.consumeName();
            if (((!self.isEof()) and (self.nextByteUnchecked() == 40))) {
                _ = self.advance(1);
                if (std.ascii.eqlIgnoreCase(value, "url")) {
                    if (self.consumeUnquotedUrl()) |tok| {
                        _ = &tok;
                        return tok;
                    }
                    return .{ .function = value };
                }
                _ = self.seeFunction(value);
                return .{ .function = value };
            }
            return .{ .ident = value };
    }

pub fn consumeName(self: *Tokenizer) []const u8 {
            const start_pos = self.position;
            var value_bytes: CopyOnWriteStr = undefined;
            _ = &value_bytes;
            while (true) {
                if (self.isEof()) {
                    return self.sliceFrom(start_pos);
                }
                switch (self.nextByteUnchecked()) {
97...122, 65...90, 48...57, '_', '-' => {
_ = self.advance(1);
},
'\\', 0 => {
value_bytes = .{ .borrowed = self.sliceFrom(start_pos) };
                break;
},
128...191 => {
_ = self.consumeContinuationByte();
},
192...239 => {
_ = self.advance(1);
},
240...255 => {
_ = self.consume4byteIntro();
},
else => {
return self.sliceFrom(start_pos);
},
}
            }
            while ((!self.isEof())) {
                const b = self.nextByteUnchecked();
                switch (b) {
97...122, 65...90, 48...57, '_', '-' => {
_ = self.advance(1);
                _ = value_bytes.appendByte(self.allocator, b);
},
'\\' => {
if (self.hasNewlineAt(1)) {
                    break;
                }
                _ = self.advance(1);
                var esc_buf: [4]u8 = undefined;
                _ = &esc_buf;
                const esc_len = self.encodeEscape((&esc_buf));
                _ = value_bytes.append(self.allocator, esc_buf[0..esc_len]);
},
0 => {
_ = self.advance(1);
                _ = value_bytes.append(self.allocator, REPLACEMENT_CHAR_UNICODE[0..]);
},
128...191 => {
_ = self.consumeContinuationByte();
                _ = value_bytes.appendByte(self.allocator, b);
},
192...239 => {
_ = self.advance(1);
                _ = value_bytes.appendByte(self.allocator, b);
},
240...255 => {
_ = self.consume4byteIntro();
                _ = value_bytes.appendByte(self.allocator, b);
},
else => {
break;
},
}
            }
            return value_bytes.toSlice();
    }

pub fn consumeQuotedString(self: *Tokenizer, comptime single_quote: bool) QuotedStringResult {
            _ = self.advance(1);
            const start_pos = self.position;
            var string_bytes: CopyOnWriteStr = undefined;
            _ = &string_bytes;
            while (true) {
                if (self.isEof()) {
                    return .{ .str = self.sliceFrom(start_pos) };
                }
                switch (self.nextByteUnchecked()) {
'"' => {
if ((!single_quote)) {
                    const value = self.sliceFrom(start_pos);
                    _ = self.advance(1);
                    return .{ .str = value };
                }
                _ = self.advance(1);
},
'\'' => {
if (single_quote) {
                    const value = self.sliceFrom(start_pos);
                    _ = self.advance(1);
                    return .{ .str = value };
                }
                _ = self.advance(1);
},
'\\', 0 => {
string_bytes = .{ .borrowed = self.sliceFrom(start_pos) };
                break;
},
10, 13, FORM_FEED_BYTE => {
return .{ .str = self.sliceFrom(start_pos), .bad = true };
},
128...191 => {
_ = self.consumeContinuationByte();
},
240...255 => {
_ = self.consume4byteIntro();
},
else => {
_ = self.advance(1);
},
}
            }
            while ((!self.isEof())) {
                const b = self.nextByteUnchecked();
                switch (b) {
10, 13, FORM_FEED_BYTE => {
return .{ .str = string_bytes.toSlice(), .bad = true };
},
'"' => {
_ = self.advance(1);
                if ((!single_quote)) {
                    break;
                }
},
'\'' => {
_ = self.advance(1);
                if (single_quote) {
                    break;
                }
},
'\\' => {
_ = self.advance(1);
                if ((!self.isEof())) {
                    switch (self.nextByteUnchecked()) {
10, FORM_FEED_BYTE, 13 => {
_ = self.consumeNewline();
},
else => {
var esc_buf: [4]u8 = undefined;
                    _ = &esc_buf;
                    const esc_len = self.encodeEscape((&esc_buf));
                    _ = string_bytes.append(self.allocator, esc_buf[0..esc_len]);
},
}
                }
                continue;
},
0 => {
_ = self.advance(1);
                _ = string_bytes.append(self.allocator, REPLACEMENT_CHAR_UNICODE[0..]);
                continue;
},
128...191 => {
_ = self.consumeContinuationByte();
},
240...255 => {
_ = self.consume4byteIntro();
},
else => {
_ = self.advance(1);
},
}
                _ = string_bytes.appendByte(self.allocator, b);
            }
            return .{ .str = string_bytes.toSlice() };
    }

pub fn consumeUnquotedUrl(self: *Tokenizer) ?Token {
            const start_position = self.position;
            const from_start = self.src[self.position..];
            var newlines: u32 = 0;
            _ = &newlines;
            var last_newline: usize = 0;
            _ = &last_newline;
            var found_printable_char = false;
            _ = &found_printable_char;
            var offset: usize = 0;
            _ = &offset;
            var b: u8 = undefined;
            _ = &b;
            while (true) {
                defer {
                offset = (offset + 1);
                }
                if ((offset < from_start.len)) {
                    b = from_start[@as(usize, @intCast(offset))];
                } else {
                    self.position = self.src.len;
                    break;
                }
                switch (b) {
' ', 9 => {

