pub fn consume_until_end_of_block(block_type: BlockType, tokenizer: *Tokenizer) void {
        const BlockStack = SmallList(BlockType, 16);
        _ = &BlockStack;
        var stack: BlockStack = .{};
        _ = &stack;
        _ = stack.appendAssumeCapacity(block_type);
        while (true) {
            const tok = (switch (tokenizer.next()) {
.result => |v| v,
.err => break,
});
            if (BlockType.closing((&tok))) |b| {
                _ = &b;
                if ((stack.getLastUnchecked() == b)) {
                    _ = stack.pop();
                    if ((stack.len() == 0)) {
                        return;
                    }
                }
            }
            if (BlockType.opening((&tok))) |bt| {
                _ = &bt;
                _ = stack.append(tokenizer.allocator, bt);
            }
        }
}

pub fn parse_at_rule(allocator: Allocator, start: *const ParserState, name: []const u8, input: *Parser, comptime P: type, parser: *P) Result(P.AtRuleParser.AtRule) {
        _ = &allocator;
        _ = ValidAtRuleParser(P);
        const delimiters = Delimiters{ .semicolon = true, .curly_bracket = true };
        var closure: AtRulePreludeClosure(P) = .{ .name = name, .parser = parser };
        _ = &closure;
        const prelude_res = input.parseUntilBefore(delimiters, P.AtRuleParser.Prelude, (&closure), @TypeOf(closure).parsefn);
        if (prelude_res.asErr()) |e| {
            _ = &e;
            const next_t = input.next();
            if (next_t.asValue()) |tok| {
                _ = &tok;
                if (((tok.* != .open_curly) and (tok.* != .semicolon))) {
                    _ = bun.unreachablePanic("Should have consumed these delimiters", .{});
                }
            }
            return .{ .err = e };
        }
        const prelude: P.AtRuleParser.Prelude = prelude_res.result;
        const next_tok = (switch (input.next()) {
.result => |v| v.*,
.err => {
return (switch (P.AtRuleParser.ruleWithoutBlock(parser, prelude, start)) {
.result => |v| {
return .{ .result = v };
},
.err => {
return .{ .err = input.newUnexpectedTokenError(.semicolon) };
},
});
},
});
        switch (next_tok) {
.semicolon => {
switch (P.AtRuleParser.ruleWithoutBlock(parser, prelude, start)) {
.result => |v| {
return .{ .result = v };
},
.err => {
return .{ .err = input.newUnexpectedTokenError(.semicolon) };
},
}
},
.open_curly => {
var another_closure: AtRuleBlockClosure(P) = .{ .prelude = prelude, .start = start, .parser = parser };
        _ = &another_closure;
        return parse_nested_block(input, P.AtRuleParser.AtRule, (&another_closure), @TypeOf(another_closure).parsefn);
},
else => {
_ = bun.unreachablePanic("", .{});
},
}
}

pub fn parse_custom_at_rule_prelude(name: []const u8, input: *Parser, options: *const ParserOptions, comptime T: type, at_rule_parser: *T) Result(AtRulePrelude(T.CustomAtRuleParser.Prelude)) {
        _ = ValidCustomAtRuleParser(T);
