pub fn parse_until_before(parser: *Parser, delimiters_: Delimiters, error_behavior: ParseUntilErrorBehavior, comptime T: type, closure: anytype, comptime parse_fn: *const fn (@TypeOf(closure), *Parser) Result(T)) Result(T) {
        const delimiters = bun.bits.@"or"(Delimiters, parser.stop_before, delimiters_);
        var start_block = parser.at_start_of;
        _ = &start_block;
        if ((start_block != null)) {
            parser.at_start_of = null;
        }
        var delimited_parser = Parser{ .input = parser.input, .at_start_of = start_block, .stop_before = delimiters, .import_records = parser.import_records, .flags = parser.flags, .extra = parser.extra };
        _ = &delimited_parser;
        const final_res = delimited_parser.parseEntirely(T, closure, parse_fn);
        if (((error_behavior == .stop) and final_res.isErr())) {
            return final_res;
        }
        if (delimited_parser.at_start_of) |block_type| {
            _ = &block_type;
            _ = consume_until_end_of_block(block_type, (&delimited_parser.input.tokenizer));
        }
        while (true) {
            if (bun.bits.contains(Delimiters, delimiters, Delimiters.fromByte(parser.input.tokenizer.nextByte()))) {
                break;
            }
            switch (parser.input.tokenizer.next()) {
.result => |token| {
if (BlockType.opening((&token))) |block_type| {
                _ = &block_type;
                _ = consume_until_end_of_block(block_type, (&parser.input.tokenizer));
            }
},
else => {
break;
},
}
        }
        return final_res;
}

pub fn parse_until_after(parser: *Parser, delimiters: Delimiters, error_behavior: ParseUntilErrorBehavior, comptime T: type, closure: anytype, comptime parsefn: *const fn (@TypeOf(closure), *Parser) Result(T)) Result(T) {
        const result = parse_until_before(parser, delimiters, error_behavior, T, closure, parsefn);
        const is_err = result.isErr();
        if (((error_behavior == .stop) and is_err)) {
            return result;
        }
        const next_byte = parser.input.tokenizer.nextByte();
        if (((next_byte != null) and (!bun.bits.contains(Delimiters, parser.stop_before, .fromByte((next_byte.?)))))) {
            if (bun.Environment.isDebug) {
                _ = bun.debugAssert(bun.bits.contains(Delimiters, delimiters, Delimiters.fromByte((next_byte.?))));
            }
            _ = parser.input.tokenizer.advance(1);
            if (((next_byte.?) == 123)) {
                _ = consume_until_end_of_block(BlockType.curly_bracket, (&parser.input.tokenizer));
            }
        }
        return result;
}

pub fn parse_nested_block(parser: *Parser, comptime T: type, closure: anytype, comptime parsefn: *const fn (@TypeOf(closure), *Parser) Result(T)) Result(T) {
        if ((parser.at_start_of == null)) {
            _ = @panic("A nested parser can only be created when a Function, ParenthisisBlock, SquareBracketBlock, or CurlyBracketBlock token was just consumed.");
        }
        const block_type: BlockType = parser.at_start_of.?;
        parser.at_start_of = null;
        const closing_delimiter = (switch (block_type) {
.curly_bracket => Delimiters{ .close_curly_bracket = true },
.square_bracket => Delimiters{ .close_square_bracket = true },
.parenthesis => Delimiters{ .close_parenthesis = true },
});
        var nested_parser = Parser{ .input = parser.input, .stop_before = closing_delimiter, .import_records = parser.import_records, .flags = parser.flags, .extra = parser.extra };
        _ = &nested_parser;
        const result = nested_parser.parseEntirely(T, closure, parsefn);
        if (nested_parser.at_start_of) |block_type2| {
            _ = &block_type2;
            _ = consume_until_end_of_block(block_type2, (&nested_parser.input.tokenizer));
        }
        _ = consume_until_end_of_block(block_type, (&parser.input.tokenizer));
        return result;
}

