                    if ((buf[@as(usize, @intCast(i))] != 48)) {
                        if ((buf[@as(usize, @intCast(i))] == 46)) {
                            new_coeff_end = i;
                        }
                        break;
                    }
                    new_coeff_end = i;
                }
            }
        }
        var real_end: usize = new_coeff_end;
        _ = &real_end;
        if (pos_exp) |posexp| {
            _ = &posexp;
            const exp_len = (len - posexp);
            if ((new_coeff_end != posexp)) {
                {
                    var i: i32 = 0;
                    _ = &i;
                    const __end_11 = exp_len;
                    while (i < __end_11) : (i += 1) {
                        buf[cp_cast_int(usize, (new_coeff_end + i))] = buf[@as(usize, @intCast((posexp + i)))];
                    }
                }
            }
            real_end = (new_coeff_end + exp_len);
        }
        var result: []u8 = undefined;
        _ = &result;
        if (sign) |sgn| {
            _ = &sgn;
            if (((buf[1] == 48) and (buf[2] != 46))) {
                buf[cp_cast_int(usize, 1)] = sgn;
                result = buf[1..real_end];
            } else {
                _ = bun.debugAssert((buf[0] == 48));
                buf[cp_cast_int(usize, 0)] = sgn;
                result = buf[0..real_end];
            }
        } else {
            if (((buf[0] == 48) and (buf[1] != 46))) {
                result = buf[1..real_end];
            } else {
                result = buf[0..real_end];
            }
        }
        const notation = Notation{ .decimal_point = (pos_dot < new_coeff_end), .scientific = (pos_exp != null) };
        return .{ result, notation };
}

pub inline fn fract(val: f32) f32 {
        return (val - @trunc(val));
}

pub fn f32_length_with_5_digits(n_input: f32) usize {
        var n = std.math.round((n_input * 100000.0));
        _ = &n;
        var count: usize = 0;
        _ = &count;
        var i: usize = 0;
        _ = &i;
        while ((n >= 1.0)) : (i = (i + 1)) {
            const rem = @mod(n, 10.0);
            if (((i > 4) or (rem != 0.0))) {
                count = (count + 1);
            }
            n = (n / 10.0);
        }
        return count;
}
